import java.util.concurrent.ForkJoinPool;

int cores = Runtime.getRuntime().availableProcessors();
int commonPoolParallelism = ForkJoinPool.commonPool().getParallelism();
// On a 2-vCPU container, commonPoolParallelism == 1!

// ANTI-PATTERN: Nested .join() on shared commonPool() deadlocks!
CompletableFuture<String> outer = CompletableFuture.supplyAsync(() -> {
    CompletableFuture<String> inner = CompletableFuture.supplyAsync(() -> fetchRemote());
    return inner.join(); // Blocks worker while inner waits in same queue!
});

ExecutorService ioPool = new ThreadPoolExecutor(
    32, 64, 60L, TimeUnit.SECONDS,
    new ArrayBlockingQueue<>(512),
    new ThreadPoolExecutor.AbortPolicy()
);

CompletableFuture<String> cf = CompletableFuture.supplyAsync(() -> callDb(), ioPool);

CompletableFuture<OrderSummary> pipeline = fetchUserAsync(userId, ioPool)
    .thenComposeAsync(user -> fetchOrdersAsync(user.id(), ioPool), ioPool)
    .thenApplyAsync(orders -> summarizeCpu(orders), cpuPool);

try (ExecutorService vPool = Executors.newVirtualThreadPerTaskExecutor()) {
    CompletableFuture<String> res = CompletableFuture.supplyAsync(() -> callBlockingApi(), vPool);
    return res.orTimeout(2, TimeUnit.SECONDS).join();
}

CompletableFuture<String> a = fetchA(ioPool).orTimeout(150, TimeUnit.MILLISECONDS).exceptionally(ex -> "fallbackA");
CompletableFuture<String> b = fetchB(ioPool).orTimeout(150, TimeUnit.MILLISECONDS).exceptionally(ex -> "fallbackB");
CompletableFuture<List<String>> combined = CompletableFuture.allOf(a, b)
    .thenApply(v -> List.of(a.join(), b.join())); // Safe: both already completed!

def check_commonpool_health(queued_submissions: int, active_threads: int, parallelism: int) -> str:
    if queued_submissions > parallelism * 4 and active_threads >= parallelism:
        return 'ALERT_COMMONPOOL_STARVATION'
    return 'HEALTHY'
